"use client";

import {
  FramecnIcon,
  mixOklch,
  useFramecnMode,
  useFramecnTheme,
} from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";

export type RadioState = "unchecked" | "checked";

type RadioSize = "sm" | "default" | "lg";

export interface RadioProps {
  state?: RadioState;
  style?: RadioStyle;
  label?: string;
  size?: RadioSize;
  theme?: Partial<FramecnTheme>;
  primary?: string;
  className?: string;
}
const SIZE_STYLES: Record<
  RadioSize,
  {
    box: number;
    fontSize: number;
    gap: number;
  }
> = {
  default: { box: 16, fontSize: 14, gap: 8 },
  lg: { box: 20, fontSize: 14, gap: 8 },
  sm: { box: 14, fontSize: 12, gap: 8 },
};

export interface RadioStyle {
  ringBorderColor: string;
  dotOpacity: number;
  dotScale: number;
}

export interface RadioStyleContext {
  uncheckedBorder: string;
  checkedBorder: string;
  dotColor: string;
}

export const radioStyleContext = (theme: FramecnTheme): RadioStyleContext => ({
  checkedBorder: theme.input,
  dotColor: theme.primary,
  uncheckedBorder: theme.input,
});

export const radioStyle = (
  state: RadioState,
  ctx: RadioStyleContext
): RadioStyle => {
  switch (state) {
    case "checked": {
      return {
        dotOpacity: 1,
        dotScale: 1,
        ringBorderColor: ctx.checkedBorder,
      };
    }
    default: {
      return {
        dotOpacity: 0,
        dotScale: 0.4,
        ringBorderColor: ctx.uncheckedBorder,
      };
    }
  }
};

export const Radio = ({
  state = "unchecked",
  style,
  label,
  size = "default",
  theme: themeOverride,
  primary,
  className,
}: RadioProps) => {
  const theme = useFramecnTheme({
    ...themeOverride,
    ...(primary ? { primary } : {}),
  });
  const mode = useFramecnMode();
  const sizeStyle = SIZE_STYLES[size];
  const ctx = radioStyleContext(theme);
  const v = style ?? radioStyle(state, ctx);
  const boxSize = sizeStyle.box;
  return (
    <div
      style={{
        alignItems: "center",
        background: "transparent",
        display: "flex",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        inset: 0,
        justifyContent: "center",
        position: "absolute",
      }}
    >
      <span
        className={className}
        style={{
          alignItems: "center",
          display: "inline-flex",
          gap: sizeStyle.gap,
        }}
      >
        <span
          style={{
            alignItems: "center",
            background:
              mode === "dark"
                ? mixOklch(theme.input, "transparent", 0.7)
                : "transparent",
            border: `1px solid ${v.ringBorderColor}`,
            borderRadius: "50%",
            boxShadow: "0 1px 2px rgb(0 0 0 / 5%)",
            boxSizing: "border-box",
            display: "flex",
            height: boxSize,
            justifyContent: "center",
            width: boxSize,
          }}
        >
          <FramecnIcon
            name="Circle"
            size={boxSize / 2}
            color={ctx.dotColor}
            style={{
              fill: ctx.dotColor,
              opacity: v.dotOpacity,
              transform: `scale(${v.dotScale})`,
            }}
          />
        </span>
        {label !== undefined && (
          <span
            style={{
              color: theme.foreground,
              fontSize: sizeStyle.fontSize,
              fontWeight: 500,
              lineHeight: "20px",
            }}
          >
            {label}
          </span>
        )}
      </span>
    </div>
  );
};

"use client";

import {
  easings,
  mixOklch,
  useFramecnTheme,
  useStateTransition,
} from "@/lib/framecn-ui";
import type { FramecnTheme, Step } from "@/lib/framecn-ui";
import {
  radioStyle,
  radioStyleContext,
} from "@/components/framecn/radio";
import type {
  RadioState,
  RadioStyle,
} from "@/components/framecn/radio";

export const DEFAULT_DURATION = 10;

export const tweenRadioStyle = (
  a: RadioStyle,
  b: RadioStyle,
  t: number
): RadioStyle => ({
  dotOpacity: a.dotOpacity + (b.dotOpacity - a.dotOpacity) * t,
  dotScale: a.dotScale + (b.dotScale - a.dotScale) * t,
  ringBorderColor: mixOklch(a.ringBorderColor, b.ringBorderColor, t),
});

export interface RadioTransitionOptions {
  theme?: Partial<FramecnTheme>;
  mode?: "light" | "dark";
  primary?: string;
  speed?: number;
  defaultDuration?: number;
}

export const useRadioTransition = (
  steps: Step<RadioState>[],
  opts: RadioTransitionOptions = {}
): RadioStyle => {
  const {
    theme: themeOverride,
    mode,
    primary,
    speed = 1,
    defaultDuration = DEFAULT_DURATION,
  } = opts;
  const theme = useFramecnTheme(
    { ...themeOverride, ...(primary ? { primary } : {}) },
    mode
  );
  const ctx = radioStyleContext(theme);
  const { from, to, progress } = useStateTransition(
    steps,
    "unchecked",
    speed,
    defaultDuration
  );
  const t = easings.out(progress);
  return tweenRadioStyle(radioStyle(from, ctx), radioStyle(to, ctx), t);
};
